import type { Metadata } from "next";
import Image from "next/image";
import Link from "next/link";
import { Suspense } from "react";
import { searchMovies } from "@/lib/tmdb/movies";
import { getTmdbPosterUrl } from "@/lib/tmdb/image";
import { BookmarkButton } from "@/components/bookmark-button";
import SearchForm from "@/components/movies/search-form";

export const metadata: Metadata = { title: "영화 검색" };

interface SearchPageProps {
  searchParams: Promise<{ query?: string | string[] }>;
}

const heroMainClass = "mx-auto flex min-h-[calc(100vh-128px)] w-full max-w-6xl flex-1 flex-col items-center justify-center px-4 py-12 sm:px-6";

export default function SearchPage({ searchParams }: SearchPageProps) {
  return (
    <Suspense
      fallback={
        <main className={heroMainClass}>
          <SearchForm query="" />
        </main>
      }
    >
      <SearchScreen searchParams={searchParams} />
    </Suspense>
  );
}

async function SearchScreen({ searchParams }: SearchPageProps) {
  const { query: rawQuery } = await searchParams;
  const query = (Array.isArray(rawQuery) ? rawQuery[0] : rawQuery)?.trim() ?? "";

  if (!query) {
    return (
      <main className={heroMainClass}>
        <SearchForm query="" />
      </main>
    );
  }

  return (
    <main className="mx-auto flex w-full max-w-6xl flex-1 flex-col px-4 py-8 sm:px-6 sm:py-10">
      <SearchForm key={query} query={query} />
      <Suspense
        fallback={<p role="status" className="py-12 text-center text-sm text-gray-500">검색 결과를 불러오는 중이에요.</p>}
      >
        <SearchResults query={query} />
      </Suspense>
    </main>
  );
}

async function SearchResults({ query }: { query: string }) {
  const { results, total_results } = await searchMovies(query);

  return (
    <>
      <div className="mb-4 flex flex-wrap items-baseline justify-between gap-2">
        <h2 className="text-sm font-semibold text-gray-900">‘{query}’ 검색 결과</h2>
        <p className="text-xs text-gray-400">영화 {total_results}편 · 1페이지</p>
      </div>

      {results.length === 0 ? (
        <p className="rounded-lg border border-dashed border-gray-300 bg-white px-5 py-12 text-center text-sm text-gray-500">
          검색 결과가 없어요.
        </p>
      ) : (
        <ul className="grid grid-cols-1 overflow-hidden border border-indigo-300 bg-white/40 md:grid-cols-2">
          {results.map((movie) => {
            const posterUrl = getTmdbPosterUrl(movie.poster_path);

            return (
              <li key={movie.id} className="flex min-w-0 gap-3 border-b border-r border-indigo-200 p-3 sm:gap-4 sm:p-4">
                <Link
                  href={`/movies/${movie.id}`}
                  aria-label={`${movie.title} 상세 보기`}
                  className="relative h-32 w-20 shrink-0 overflow-hidden rounded-lg bg-gray-200 sm:h-36 sm:w-24"
                >
                  {posterUrl ? (
                    <Image src={posterUrl} alt={`${movie.title} 포스터`} fill sizes="96px" className="object-cover" />
                  ) : (
                    <div className="flex h-full w-full items-center justify-center bg-gray-200 text-xs text-gray-600">
                      이미지 없음
                    </div>
                  )}
                </Link>

                <div className="flex min-w-0 flex-1 flex-col items-start">
                  <Link href={`/movies/${movie.id}`} className="line-clamp-1 text-sm font-bold text-gray-950 hover:text-indigo-700">
                    {movie.title}
                  </Link>
                  <p className="mt-1 line-clamp-1 text-[11px] text-gray-400">
                    {movie.original_title} · {movie.release_date}
                  </p>
                  <p className="mt-2 line-clamp-2 text-xs leading-5 text-gray-600">{movie.overview}</p>

                  <div className="mt-auto flex items-center gap-3 pt-2">
                    <Link href={`/movies/${movie.id}`} className="text-xs font-semibold text-indigo-600 hover:text-indigo-800">
                      상세 보기 →
                    </Link>
                    <BookmarkButton movieId={movie.id} variant="inline" title={movie.title} />
                  </div>
                </div>
              </li>
            );
          })}
        </ul>
      )}
    </>
  );
}
