import "server-only";

export class TmdbError extends Error {
  constructor(
    public status: number,
    message: string,
  ) {
    super(message);
    this.name = "TmdbError";
  }
}

type Params = Record<string, string | number | boolean>;

// Server Component에서만 호출해요. 토큰이 브라우저로 전달되지 않아요.
export async function tmdbFetch<T>(path: string, params: Params = {}): Promise<T> {
  const baseUrl = process.env.TMDB_API_BASE_URL;
  const token = process.env.TMDB_ACCESS_TOKEN;

  if (!baseUrl || !token) {
    throw new Error("TMDB 환경 변수가 필요해요.");
  }

  const url = new URL(`${baseUrl.replace(/\/$/, "")}/${path}`);
  url.searchParams.set("language", "ko-KR");
  for (const [key, value] of Object.entries(params)) {
    url.searchParams.set(key, String(value));
  }

  const response = await fetch(url, {
    headers: { Authorization: `Bearer ${token}`, accept: "application/json" },
  });

  if (!response.ok) {
    throw new TmdbError(response.status, `TMDB 요청에 실패했어요: ${response.status}`);
  }

  return response.json();
}
